code.source:
#include <iostream>
#include <stack>
using namespace std;

int main() {
    stack<int> s;
    s.push(1);
    s.push(2);
    s.push(3);
    cout << s.top() << endl;
    s.pop();
    cout << s.top() << endl;
    cout << s.size() << endl;
    return 0;
}

#include <iostream>
#include <queue>
#include <string>
using namespace std;

int main() {
    queue<string> q;
    q.push("Asha");
    q.push("Ravi");
    q.push("Meera");
    cout << q.front() << endl;
    q.pop();
    cout << q.front() << " " << q.back() << endl;
    return 0;
}

